        throw new InvalidValueError(
          el.value,
          value,
          Object.keys(el.options),
          originalMessage
        )
      }
      // Convert bigint to number for currentPluralValue
      const numericValue =
        typeof value === 'bigint' ? Number(value) : (value as number)
      result.push(
        ...formatToParts(
          opt.value,
          locales,
          formatters,
          formats,
          values,
          numericValue - (el.offset || 0)
        )
      )
      continue
    }
  }
  return mergeLiteral(result)
